// Server-side Sentry + OpenTelemetry initialization for the Node.js runtime.
//
// Imported by instrumentation.ts in the "nodejs" runtime block. This replaces
// the separate sentry.server.config.ts that was generated by the Sentry wizard.

import * as Sentry from "@sentry/nextjs"
import {
  BatchSpanProcessor,
  ConsoleSpanExporter,
  SimpleSpanProcessor,
} from "@opentelemetry/sdk-trace-base"
import type { SpanProcessor } from "@opentelemetry/sdk-trace-base"
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http"
import diagnosticsChannel from "node:diagnostics_channel"
import type { IncomingMessage, ServerResponse } from "node:http"
import { createRequestLogEntry, hasOtlpEndpointConfig } from "./otel-utils"
import {
  SENTRY_HTTP_INTEGRATION_OPTIONS,
  installOpenTelemetry,
} from "./otel-setup"
import { parseSampleRate } from "./sentry-utils"
import { env } from "@/env"
import { validateEnv } from "../validateEnv"
import { ValidationError } from "yup"

// Validate the full environment schema once at server startup (Node runtime).
// validateEnv() is skipped in next.config.js during Docker builds
// (NEXT_BUILD_CI=1) because NEXT_PUBLIC_* values are injected at runtime, not
// present at build — so this startup check is where deployed pods get validated
// (presence AND format). `abortEarly: false` means a single failure reports
// every bad var at once. On failure we log and exit so the pod crash-loops with
// a clear message instead of silently serving broken pages — an uncaught throw
// here is not guaranteed to terminate the process (Next may log and continue),
// hence the explicit process.exit(1).
try {
  validateEnv()
} catch (err) {
  const detail =
    err instanceof ValidationError ? err.errors.join("\n  - ") : String(err)
  console.error(
    `[startup] Environment validation failed:\n  - ${detail}\n` +
      "Exiting to prevent broken deployment.",
  )
  process.exit(1)
}

// Inject service.version into OTEL_RESOURCE_ATTRIBUTES so the OTEL SDK's
// EnvDetector picks it up alongside any other attributes set via env.
// Simpler than interpolating OTEL_RESOURCE_ATTRIBUTES in ol-infrastructure.
const appVersion = env("NEXT_PUBLIC_VERSION")
if (appVersion) {
  const prefix = `service.version=${encodeURIComponent(appVersion)}`
  const existing = process.env.OTEL_RESOURCE_ATTRIBUTES
  process.env.OTEL_RESOURCE_ATTRIBUTES = existing
    ? `${prefix},${existing}`
    : prefix
}

/**
 * Span processors that export to Alloy/Tempo, appended after Sentry's own.
 *
 * There is no resource-rewriting processor here any more. The provider is
 * built with the real Resource (see otel-setup.ts), so spans carry the right
 * service.name from birth rather than having it patched on at export.
 *
 * LOCAL TESTING (no Grafana Alloy required):
 * Set OTEL_TRACES_EXPORTER=console and OTEL_TRACES_SAMPLER_ARG=1.0 to print
 * completed spans as JSON to stdout. See env/frontend.env for details.
 */
function buildSpanProcessors(): SpanProcessor[] {
  if (hasOtlpEndpointConfig(process.env)) {
    return [new BatchSpanProcessor(new OTLPTraceExporter())]
  }
  if (process.env.OTEL_TRACES_EXPORTER === "console") {
    return [new SimpleSpanProcessor(new ConsoleSpanExporter())]
  }
  return []
}

declare global {
  // eslint-disable-next-line no-var
  var __NEXT_REQUEST_LOGGER_SUBSCRIBED__: boolean | undefined
}

// Skip Next-internal paths (static chunks, HMR, dev endpoints) and the
// favicon. These never get OTEL traces (Sentry's HttpInstrumentation already
// filters them) so they're noise for the OTEL-coverage diagnostic, and in
// prod they mostly hit the CDN anyway. RSC fetches go to real route paths
// (e.g. /courses?_rsc=...) and are not filtered.
const NEXT_INTERNAL_PATH = /^\/(_next\/|__nextjs_|favicon\.ico)/

/**
 * Subscribe to Node's built-in HTTP server diagnostics channels and emit a
 * structured JSON log line per completed request. This runs independently of
 * the OTEL sampler — every request is logged regardless of OTEL_TRACES_SAMPLER_ARG
 * — so the logs can be used as ground truth for verifying OTEL trace coverage.
 *
 * Enabled by default; set NEXT_SERVER_REQUEST_LOGGING=false to disable.
 *
 * The channels (`http.server.request.start`, `http.server.response.finish`)
 * are marked Experimental in Node 24 and 25, but are the same surface that
 * Sentry/OTEL/Datadog subscribe to internally; the API has been stable in
 * practice for years.
 *
 * Guarded against double-subscription via a globalThis flag — instrumentation
 * hooks can be re-evaluated on dev reloads or worker restarts, and stacked
 * subscriptions would duplicate every log line.
 */
function subscribeRequestLogger(): void {
  if (globalThis.__NEXT_REQUEST_LOGGER_SUBSCRIBED__) return
  globalThis.__NEXT_REQUEST_LOGGER_SUBSCRIBED__ = true

  const startTimes = new WeakMap<IncomingMessage, bigint>()

  diagnosticsChannel.subscribe("http.server.request.start", (message) => {
    const { request } = message as { request: IncomingMessage }
    startTimes.set(request, process.hrtime.bigint())
  })

  diagnosticsChannel.subscribe("http.server.response.finish", (message) => {
    const { request, response } = message as {
      request: IncomingMessage
      response: ServerResponse
    }
    const start = startTimes.get(request)
    if (start === undefined) return
    startTimes.delete(request)
    if (request.url && NEXT_INTERNAL_PATH.test(request.url)) return
    const durationMs = Number((process.hrtime.bigint() - start) / 1_000_000n)
    console.info(
      JSON.stringify(createRequestLogEntry({ request, response, durationMs })),
    )
  })
}

if (process.env.NEXT_SERVER_REQUEST_LOGGING !== "false") {
  subscribeRequestLogger()
}

// Root rate for our own sampler, wrapped in ParentBased so an upstream
// decision wins. Traefik is the root for next.learn.mit.edu and samples every
// request, and the Alloy tail sampler makes the real keep/drop call once it can
// see the whole trace -- so this governs CPU spent building spans, not what
// ends up in Tempo. Defaults to 1.0.
//
// OTEL_TRACES_SAMPLER is still not read: the sampler is constructed directly
// in otel-setup.ts, and honouring the variable would mean reimplementing the
// SDK's env parsing for no gain.
const otelSampleRate = parseSampleRate(process.env.OTEL_TRACES_SAMPLER_ARG, 1)

// Sentry's own rate, independent of the above. Applied to transactions that
// already exist, so lowering it costs Tempo nothing.
const sentrySampleRate = parseSampleRate(
  env("NEXT_PUBLIC_SENTRY_TRACES_SAMPLE_RATE"),
  1,
)

Sentry.init({
  dsn: env("NEXT_PUBLIC_SENTRY_DSN"),
  release: env("NEXT_PUBLIC_VERSION"),
  environment: env("NEXT_PUBLIC_SENTRY_ENV"),

  // We build the provider, sampler, resource, propagator and context manager
  // ourselves in installOpenTelemetry() below. See otel-setup.ts for why.
  skipOpenTelemetrySetup: true,

  // Sentry stops instrumenting node:http for spans when skipOpenTelemetrySetup
  // is set (_shouldUseOtelHttpInstrumentation in integrations/http.ts returns
  // false), unless spans is passed explicitly. Without this there is no server
  // span at all and the SSR render becomes invisible -- a silent failure, so
  // it is asserted in otel-setup.test.ts via SENTRY_HTTP_INTEGRATION_OPTIONS.
  integrations: [Sentry.httpIntegration(SENTRY_HTTP_INTEGRATION_OPTIONS)],

  // No longer the OTEL sampler. Our provider's sampler governs span creation;
  // this is the fraction of already-created transactions Sentry keeps, applied
  // by beforeSendTransaction below. The two are now independent by
  // construction rather than by keeping one of them pinned at 1.0.
  beforeSendTransaction: (transaction) => {
    return Math.random() < sentrySampleRate ? transaction : null
  },

  debug: false,
})

// After Sentry.init: SentrySpanProcessor needs a client to report through, and
// Sentry has by then declined to register its own globals.
installOpenTelemetry({
  sampleRate: otelSampleRate,
  spanProcessors: buildSpanProcessors(),
})

// Throws if the pipeline is inconsistent -- e.g. a context manager or
// propagator Sentry cannot work with. Cheap, and the alternative is finding
// out from missing spans in production.
Sentry.validateOpenTelemetrySetup()
